#include <iostream>
using namespace std;

int main()
{
    long long n, m, x, y, a, b, x1, y1, x2, y2;
    long long s, e, mid;
    long long i, j, k;

    cin >> n >> m >> x >> y >> a >> b;

    if (b > a)
    {
        j = b;
        i = a;
    }
    else
    {
        j = a;
        i = b;
    }

    while (j % i != 0)
    {
        k = j % i;
        j = i;
        i = k;
    }

    a /= i;
    b /= i;

    if (a == b)
    {
        a = 1;
        b = 1;
    }

    s = 1;
    e = n;

    while (s < e - 1)
    {
        mid = (s + e) / 2;
        if (mid * a <= n && mid * b <= m)
            s = mid;
        else
            e = mid;
    }

    a *= s;
    b *= s;

    if (a % 2 == 0)
        x1 = x - a / 2;
    else
        x1 = x - a / 2 - 1;

    x2 = x1 + a;

    if (b % 2 == 0)
        y1 = y - b / 2;
    else
        y1 = y - b / 2 - 1;

    y2 = y1 + b;

    if (x1 < 0)
    {
        x1 = 0;
        x2 = a;
    }

    if (x2 > n)
    {
        x1 = n - a;
        x2 = n;
    }

    if (y1 < 0)
    {
        y1 = 0;
        y2 = b;
    }

    if (y2 > m)
    {
        y1 = m - b;
        y2 = m;
    }

    cout << x1 << " " << y1 << " " << x2 << " " << y2 << endl;
    return 0;
}

